create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
begin;
select plan(26);
select has_table('public','customer_contacts','customer contacts table exists');
select has_table('public','customer_interactions','customer interaction history exists');
select has_table('public','customer_loyalty_rules','loyalty rules table exists');
select has_table('public','customer_reward_ledger','append-only reward ledger exists');
select has_column('public','customers','customer_type','customer category is stored on customer');
select has_column('public','customers','is_walk_in_profile','anonymous walk-in profile is supported');
select has_table('public','customer_addresses','existing address book is reused');
select ok((select relrowsecurity from pg_class where oid='public.customer_contacts'::regclass),'contacts RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.customer_interactions'::regclass),'interactions RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.customer_loyalty_rules'::regclass),'loyalty rules RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.customer_reward_ledger'::regclass),'reward ledger RLS enabled');
select ok(has_table_privilege('authenticated','public.customer_contacts','SELECT'),'authenticated owner workspace can read contacts subject to RLS');
select ok(not has_table_privilege('authenticated','public.customer_contacts','INSERT'),'clients cannot directly insert contacts');
select ok(not has_table_privilege('authenticated','public.customer_reward_ledger','INSERT'),'clients cannot directly post rewards');
select ok(not has_table_privilege('authenticated','public.customer_interactions','INSERT'),'clients cannot directly insert interactions');
select ok(not has_table_privilege('authenticated','public.customer_loyalty_rules','INSERT'),'clients cannot directly change reward rules');
select ok(has_function_privilege('authenticated','public.owner_save_customer_profile(uuid,uuid,text,text,text,text,text,text,text,text,text,text,uuid)','EXECUTE'),'authenticated can call owner-checked profile RPC');
select ok(not has_function_privilege('anon','public.owner_save_customer_profile(uuid,uuid,text,text,text,text,text,text,text,text,text,text,uuid)','EXECUTE'),'anonymous users cannot call profile RPC');
select ok(has_function_privilege('authenticated','public.owner_record_customer_reward(uuid,uuid,uuid,uuid,text,text,bigint,text,text,uuid,uuid)','EXECUTE'),'authenticated can call owner-checked reward RPC');
select ok(has_function_privilege('authenticated','public.owner_upsert_customer_address(uuid,uuid,uuid,text,text,text,text,text,boolean,uuid)','EXECUTE'),'authenticated can call owner-checked address RPC');
select ok(not has_function_privilege('anon','public.owner_record_customer_reward(uuid,uuid,uuid,uuid,text,text,bigint,text,text,uuid,uuid)','EXECUTE'),'anonymous users cannot post rewards');
select ok(not has_function_privilege('anon','public.owner_upsert_customer_address(uuid,uuid,uuid,text,text,text,text,text,boolean,uuid)','EXECUTE'),'anonymous cannot save customer addresses');
select ok(to_regclass('public.customer_reward_one_rule_award_per_order') is not null,'one rule cannot award the same order twice');
select ok(to_regprocedure('private.award_customer_rewards_on_order_completion()') is not null,'automatic reward evaluator exists');
select ok(exists(select 1 from pg_trigger where tgrelid='public.orders'::regclass and tgname='award_customer_rewards_after_order_completion' and not tgisinternal),'automatic rewards run on order completion');
select ok(position('ceil(v_unit_cost/0.70)' in pg_get_functiondef('private.owner_create_quotation(uuid,uuid,uuid,jsonb,timestamptz,text,text,uuid)'::regprocedure)) > 0,'missing rule defaults to cost-based 30 percent gross-margin floor');
select * from finish();
rollback;
